public class ImageBorderPadderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "null-image";
        }
        if (x < 0 || y < 0 || x >= img.getWidth() || y >= img.getHeight()) {
            return "out-of-range";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static int widthOf(java.awt.image.BufferedImage img) {
        return img == null ? -1 : img.getWidth();
    }

    static int heightOf(java.awt.image.BufferedImage img) {
        return img == null ? -1 : img.getHeight();
    }

    static java.awt.image.BufferedImage ramp(int w, int h) {
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
                w, h, java.awt.image.BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                int r = (x * 30 + 11) % 256;
                int gr = (y * 50 + 23) % 256;
                int b = (x * 7 + y * 13 + 61) % 256;
                img.setRGB(x, y, (r << 16) | (gr << 8) | b);
            }
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage src = ramp(4, 3);
            java.awt.image.BufferedImage padded = ImageBorderPadder.addBorder(src, 2, java.awt.Color.MAGENTA);
            java.awt.image.BufferedImage none = ImageBorderPadder.addBorder(src, 0, java.awt.Color.MAGENTA);
            check("padded width", 8, widthOf(padded));
            check("padded height", 7, heightOf(padded));
            check("top-left corner is border colour", "#FF00FF", pixel(padded, 0, 0));
            check("bottom-right corner is border colour", "#FF00FF", pixel(padded, 7, 6));
            check("source (0,0) lands at (2,2)", "#0B173D", pixel(padded, 2, 2));
            check("source (3,2) lands at (5,4)", "#657B6C", pixel(padded, 5, 4));
            check("zero thickness keeps the width", 4, widthOf(none));
            check("zero thickness copies pixel (1,1)", "#294951", pixel(none, 1, 1));
            check("source is untouched at (1,1)", "#294951", pixel(src, 1, 1));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

