import java.awt.Color;
import java.awt.image.BufferedImage;

public class ImageBorderPadder {

    public static BufferedImage addBorder(BufferedImage src, int thickness, Color color) {
        int w = src.getWidth() + 2 * thickness;
        int h = src.getHeight() + 2 * thickness;
        BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);

        int border = color.getRGB();
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                out.setRGB(x, y, border);
            }
        }

        for (int y = 0; y < src.getHeight(); y++) {
            for (int x = 0; x < src.getWidth(); x++) {
                out.setRGB(x + thickness, y + thickness, src.getRGB(x, y));
            }
        }
        return out;
    }
}
